import{_ as l,a0 as d,w as n,s as p,ao as c,I as o,x as t,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"終端基礎：Linux 終端中的目錄切換 | LCTT x X-CMD","titleTemplate":false,"description":"終端基礎：Linux 終端中的目錄切換 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"終端基礎：Linux 終端中的目錄切換 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"終端基礎：Linux 終端中的目錄切換 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20230213.2 ⭐️ Terminal Basics Series 1 Changing Directories in Linux Terminal","title":"終端基礎：Linux 終端中的目錄切換","tag":"202310","desc":""},"relativePath":"202310/20230213.2 ⭐️ Terminal Basics Series 1 Changing Directories in Linux Terminal.md","filePath":"[post].md"}'),r={name:"202310/20230213.2 ⭐️ Terminal Basics Series 1 Changing Directories in Linux Terminal.md"};function h(u,e,g,m,b,k){const i=d("Link");return n(),p("div",null,[e[15]||(e[15]=c(`<h1 id="終端基礎-linux-終端中的目錄切換" tabindex="-1">終端基礎：Linux 終端中的目錄切換 <a class="header-anchor" href="#終端基礎-linux-終端中的目錄切換" aria-label="Permalink to “終端基礎：Linux 終端中的目錄切換”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/21/062234mz9zymqc6om5924m.jpg" alt=""></p><blockquote><p>本篇文章作為終端基礎教程系列的一部分，介紹如何在 Linux 命令列中，利用絕對路徑和相對路徑實現目錄切換。</p></blockquote><p>Linux 的 <code>cd</code> 命令讓你可以輕鬆切換文件夾（即目錄）。只需提供你要切換到的文件夾路徑即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd path_to_directory</span></span></code></pre></div><p>然而對於 Linux 新人來説，可能會在路徑的指定上有所困擾。</p><p>首先，讓我們解決這個問題。</p><h3 id="理解-linux-中的路徑" tabindex="-1">理解 Linux 中的路徑 <a class="header-anchor" href="#理解-linux-中的路徑" aria-label="Permalink to “理解 Linux 中的路徑”">​</a></h3><p>在 Linux 文件系統中，路徑是用來追蹤文件位置的信息。所有的路徑都從根目錄開始，然後向下延伸。</p><p>你可以通過下面的方式查看當前所在的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pwd</span></span></code></pre></div><p>結果可能是類似於 <code>/home/username</code> 的輸出。注意，這裏的 <code>username</code> 將會是你自己的用户名。</p><p>你可以注意到，路徑是由 <code>/</code> 符號和目錄名組成的。比如路徑 <code>/home/abhishek/scripts</code>， 表示 <code>scripts</code> 是在文件夾 <code>abhishek</code> 之內，而文件夾 <code>abhishek</code> 在 <code>home</code> 文件夾之內。要注意，第一個 &#39;/&#39; 是指根目錄（即文件系統的開始處），後面的 &#39;/&#39; 則作為目錄的分隔符。</p><p><img src="https://itsfoss.com/content/images/2023/02/path-linux.webp" alt="Path in Linux"></p><blockquote><p>🖥️ 在終端中鍵入 <code>ls /</code>，然後按回車。你將會看到根目錄下的所有內容，試試看！</p></blockquote><p>接下來，讓我們學習兩種常見的路徑指定方式：絕對路徑和相對路徑。</p><p><strong>絕對路徑</strong>：這種路徑從根開始，然後一直擴展到你需要的位置。如果一個路徑是以 <code>/</code> 開頭，那就説明它是一個絕對路徑。</p><p><strong>相對路徑</strong>：這是相對於你文件系統中當前位置的路徑。如果我當前位置在 <code>/home/abhishek</code>，並且我需要去 <code>/home/abhishek/Documents</code>， 我只需要簡單地切換到 <code>Documents</code>，而不需要指定整個絕對路徑 <code>/home/abhishek/Documents</code>。</p><p>在我演示這兩種路徑的區別之前，有必要先熟悉兩個特殊的目錄標識：</p><ul><li><code>.</code> （單點）表示當前目錄。</li><li><code>..</code> （雙點）表示上一級目錄，也就是當前目錄的母目錄。</li></ul><p>這裏有一張圖形化的表示。</p><p><img src="https://itsfoss.com/content/images/2023/02/absolute-and-relative-path.png" alt="Absolute path vs relative path"></p><h3 id="利用-cd-命令變更目錄" tabindex="-1">利用 cd 命令變更目錄 <a class="header-anchor" href="#利用-cd-命令變更目錄" aria-label="Permalink to “利用 cd 命令變更目錄”">​</a></h3><p>在你已對路徑概念有所瞭解之後，我們來了解如何切換目錄。</p><blockquote><p>🖥️ 如果你<strong>僅鍵入 <code>cd</code> 並按回車鍵</strong>，無論當前位置在哪，系統都會將你帶回主目錄。試一試吧。</p></blockquote><p>敲入以下命令，你就能看到主目錄裏的所有文件夾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls</span></span></code></pre></div><p>這是我看到的情況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abhishek@ituxedo:~$ ls</span></span>
<span class="line"><span>Desktop    Downloads  Pictures  Templates  VirtualBoxVMs</span></span>
<span class="line"><span>Documents  Music      Public    Videos</span></span></code></pre></div><p>你的情況可能與此類似，但未必完全一樣。</p><p>假如你希望跳轉到 <code>Documents</code> 文件夾。由於它就在當前目錄下，這裏使用相對路徑會比較方便：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd Documents</span></span></code></pre></div><blockquote><p>💡 注意，大部分 Linux 發行版預設的終端模擬器會在提示符本身顯示出當前所在的位置。因此你不必頻繁使用 <code>pwd</code> 指令來確認自己的位置。</p></blockquote><p><img src="https://itsfoss.com/content/images/2023/02/linux-terminal-prompt.png" alt="Most Linux terminal prompts show the current location"></p><p>假如你希望切換到位於主目錄裏的 <code>Templates</code> 文件夾。</p><p>你可以使用相對路徑 <code>../Templates</code>（<code>..</code> 會讓你返回到上層目錄，即 <code>/home/username</code>，然後你就可以進入 <code>Templates</code> 文件夾了）。</p><p>但這次我們嘗試使用絕對路徑。請把下面的 <code>abhishek</code> 替換成你的用户名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /home/abhishek/Templates</span></span></code></pre></div><p>此刻你已經在 <code>Templates</code> 文件夾裏了。如何前往 <code>Downloads</code> 文件夾呢？這次我們再使用相對路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ../Downloads</span></span></code></pre></div><p>下面的圖片會回顧一下你剛才學到的所有或有關目錄切換的範例。</p><p><img src="https://itsfoss.com/content/images/2023/02/cd-command-example.svg" alt="cd command example"></p><blockquote><p>💡 別忘了你還可以使用終端的 <code>tab</code> 鍵自動補全功能。只需要鍵入命令或者文件夾名稱的前幾個字母，然後敲擊 <code>tab</code> 鍵，系統就會嘗試自動地補全命令或文件夾名稱，或者給你顯示出所有可能的選項。</p></blockquote><h3 id="故障解決" tabindex="-1">故障解決 <a class="header-anchor" href="#故障解決" aria-label="Permalink to “故障解決”">​</a></h3><p>在 Linux 終端操作切換目錄的過程中，你可能會遇到一些常見的錯誤。</p><h4 id="文件或目錄不存在" tabindex="-1">文件或目錄不存在 <a class="header-anchor" href="#文件或目錄不存在" aria-label="Permalink to “文件或目錄不存在”">​</a></h4><p>如果在你嘗試切換目錄時，出現類似下面的錯誤信息：</p><blockquote><p>bash: cd: directory_name: No such file or directory</p></blockquote><p>那麼你可能在路徑或目錄名稱上犯了誤解。這裏有幾點你需要注意的：</p><ul><li>請確定你輸入的目錄名中沒有拼寫錯誤。</li><li>Linux 系統對大小寫敏感，因此，<code>Downloads</code> 和 <code>downloads</code> 會被識別為不同的目錄。</li><li>你可能未正確指定路徑。可能你所在的位置與你預期的不同？或者你遺漏了絕對路徑中的開頭的 <code>/</code> 字符？</li></ul><p><img src="https://itsfoss.com/content/images/2023/02/common-errors-with-cd.png" alt="Common examples of &quot;no such file or directory&quot; error"></p><h4 id="非目錄錯誤" tabindex="-1">非目錄錯誤 <a class="header-anchor" href="#非目錄錯誤" aria-label="Permalink to “非目錄錯誤”">​</a></h4><p>如果你看到像下面這樣的錯誤提示：</p><blockquote><p>bash: cd: filename: Not a directory</p></blockquote><p>這表示你嘗試使用 <code>cd</code> 命令對一個文件進行操作，而不是一個目錄（文件夾）。很明顯，你不能像進入文件夾那樣“進入”一個文件，因此會出現這樣的錯誤。</p><p><img src="https://itsfoss.com/content/images/2023/02/not-a-directory-error-linux.png" alt="Not a directory error with the cd command"></p><h4 id="參數過多" tabindex="-1">參數過多 <a class="header-anchor" href="#參數過多" aria-label="Permalink to “參數過多”">​</a></h4><p>這是 Linux 新手常犯的另一個錯誤：</p><blockquote><p>bash: cd: too many arguments</p></blockquote><p><code>cd</code> 命令只接受一個參數。也就是説，你只能對命令指定一個目錄。</p><p>如果你指定了超過一個的參數，或者在路徑中誤加了空格，你就會看到這個錯誤。</p><p><img src="https://itsfoss.com/content/images/2023/02/too-many-arguments.png" alt="Too many arguments error in Linux terminal"></p><blockquote><p>🏋🏻 如果你輸入 <code>cd -</code>，它將會把你帶到前一個目錄。當你在兩個相隔較遠的地方切換時非常方便，可以避免再次輸入長路徑。</p></blockquote><h3 id="特殊目錄符號" tabindex="-1">特殊目錄符號 <a class="header-anchor" href="#特殊目錄符號" aria-label="Permalink to “特殊目錄符號”">​</a></h3><p>在結束這個教程之前，我想快速告訴你關於特殊符號 <code>~</code>。在 Linux 中，<code>~</code> 是用户主目錄的捷徑。</p><p>如果用户 <code>abhi</code> 運行它，<code>~</code> 就會代表 <code>/home/abhi</code>，如果用户 <code>prakash</code> 運行，<code>~</code> 就意味着 <code>/home/prakash</code>。</p><p>總結一下你在這個基礎教程系列中學到的所有特殊目錄標識：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">符號</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.</code></td><td style="text-align:left;">當前目錄</td></tr><tr><td style="text-align:left;"><code>..</code></td><td style="text-align:left;">上級目錄</td></tr><tr><td style="text-align:left;"><code>~</code></td><td style="text-align:left;">主目錄</td></tr><tr><td style="text-align:left;"><code>-</code></td><td style="text-align:left;">前一個目錄</td></tr></tbody></table></div><h3 id="測試你的知識" tabindex="-1">測試你的知識 <a class="header-anchor" href="#測試你的知識" aria-label="Permalink to “測試你的知識”">​</a></h3><p>下面是一些簡單的練習，用來測試你剛剛學到的關於路徑和 <code>cd</code> 命令的知識。</p><p>移動到你的主目錄，並使用這個命令創建一個嵌套的目錄結構：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p sample/dir1/dir2/dir3</span></span></code></pre></div><p>然後，一步步來試試這個：</p><ul><li>使用絕對路徑或相對路徑進入 <code>dir3</code></li><li>使用相對路徑移動到 <code>dir1</code></li><li>使用你能想像到的最短路徑進入 <code>dir2</code></li><li>使用絕對路徑切換到 <code>sample</code> 目錄</li><li>返回你的主目錄</li></ul><blockquote><p>🔑 想知道你是否全都做對了嗎？歡迎分享你的答案。</p></blockquote><p>現在你知道如何切換目錄，是不是應該學習一下如何創建它們呢？</p><p>我強烈推薦你閲讀這篇文章，瞭解一些關於終端和命令的小技巧。</p><p>如果你想了解 Linux 命令列的基礎知識，記得關注我們的 Linux 終端基礎系列教程的更多章節。</p><hr>`,79)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),s(i,{href:"https://itsfoss.com/change-directories/"},{default:a(()=>[...e[0]||(e[0]=[t("https://itsfoss.com/change-directories/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),s(i,{href:"https://itsfoss.com/author/abhishek/"},{default:a(()=>[...e[2]||(e[2]=[t("Abhishek Prakash",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),s(i,{href:"https://github.com/lkxed/"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),s(i,{href:"https://linux.cn/lctt/ChatGPT"},{default:a(()=>[...e[4]||(e[4]=[t("ChatGPT",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const T=l(r,[["render",h]]);export{y as __pageData,T as default};
